import cv2,numpy as np
from scipy.ndimage import label,find_objects
A=np.load('source_pixels.npz')['rgb'];h,w=A.shape[1:3]; yy,xx=np.mgrid[:h,:w].astype('f4')
d=cv2.DISOpticalFlow_create(cv2.DISOPTICAL_FLOW_PRESET_MEDIUM);d.setFinestScale(0);d.setGradientDescentIterations(30);d.setVariationalRefinementIterations(8)
g0=cv2.cvtColor(A[0],cv2.COLOR_RGB2GRAY);g1=cv2.cvtColor(A[1],cv2.COLOR_RGB2GRAY)
f01=d.calc(g0,g1,None); f10=d.calc(g1,g0,None)
def warp(im,mx,my):return cv2.remap(im,mx,my,cv2.INTER_LINEAR,borderMode=cv2.BORDER_REPLICATE)
def comp(a):
 m=(a[...,0]>120)&(a[...,0]>a[...,1]*1.35)&(a[...,0]>a[...,2]*1.25);ll,n=label(m);o=[]
 for i,s in enumerate(find_objects(ll),1):
  if s and s[0].stop<95:
   c=(ll[s]==i).sum()
   if c>30:o.append((c,s[1].start,s[1].stop-1,s[0].start,s[0].stop-1))
 return o
for a in [.25,.5,.75]:
 W0=warp(A[0],xx-a*f01[...,0],yy-a*f01[...,1])
 W1=warp(A[1],xx-(1-a)*f10[...,0],yy-(1-a)*f10[...,1])
 variants={'w0':W0,'w1':W1,'blend':np.clip((1-a)*W0+a*W1,0,255).astype('u1')}
 print('\\na',a,'flow old',np.median(f01[65:82,24:34],axis=(0,1)),'new',np.median(f10[65:82,43:53],axis=(0,1)))
 for k,v in variants.items(): print(k,comp(v))
